 init?(_ text:String){let pattern="^v?(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z.-]+))?(?:\\+[0-9A-Za-z.-]+)?$";guard let regex=try? NSRegularExpression(pattern:pattern),let match=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)) else{return nil};func group(_ n:Int)->String{Range(match.range(at:n),in:text).map{String(text[$0])} ?? ""};guard let a=Int(group(1)),let b=Int(group(2)),let c=Int(group(3)) else{return nil};let suffix=group(4);if !suffix.isEmpty && suffix.split(separator:".",omittingEmptySubsequences:false).contains(where:{$0.isEmpty || ($0.allSatisfy(\.isNumber) && $0.count>1 && $0.first=="0")}){return nil};major=a;minor=b;patch=c;pre=suffix}
 var core:String{"\(major).\(minor).\(patch)"}
 static func <(a:Self,b:Self)->Bool{if a.major != b.major{return a.major<b.major};if a.minor != b.minor{return a.minor<b.minor};if a.patch != b.patch{return a.patch<b.patch};if a.pre==b.pre{return false};if a.pre.isEmpty{return false};if b.pre.isEmpty{return true};let x=a.pre.split(separator:".").map(String.init),y=b.pre.split(separator:".").map(String.init);for i in 0..<min(x.count,y.count){if x[i]==y[i]{continue};let xn=x[i].allSatisfy(\.isNumber),yn=y[i].allSatisfy(\.isNumber);if xn && yn{return x[i].count==y[i].count ? x[i]<y[i]:x[i].count<y[i].count};if xn != yn{return xn};return x[i]<y[i]};return x.count<y.count}
}
struct UpdateAsset:Decodable {var name:String,browser_download_url:String,size:Int64,digest:String?}
struct APIRelease:Decodable {var tag_name:String,draft:Bool,prerelease:Bool,assets:[UpdateAsset]}
struct UpdateRelease {let tag:String,version:ReleaseVersion,prerelease:Bool,asset:UpdateAsset,checksums:UpdateAsset?}
struct UpdatePreferences:Codable {var channel="stable",automatic=true,skipped=""}
