 @MainActor private func beginInstall(_ release:UpdateRelease){busy=true;let window=NSWindow(contentRect:CGRect(x:0,y:0,width:420,height:170),styleMask:[.titled],backing:.buffered,defer:false);window.title=L10n.text("Actualización de WirePulse");window.contentView=NSHostingView(rootView:UpdateProgressView(manager:self));window.isReleasedWhenClosed=false;window.center();window.makeKeyAndOrderFront(nil);progressWindow=window;installTask=Task{do{status=L10n.text("Descargando actualización…");let package=try await download(release);try Task.checkCancellation();status=L10n.text("Instalando actualización…");installing=true;try await install(package,release:release);window.close();NSApp.terminate(nil)}catch is CancellationError{window.close()}catch let error as URLError where error.code == .cancelled{window.close()}catch{status=L10n.text("No se pudo actualizar: ")+error.localizedDescription;window.close();let alert=NSAlert();alert.messageText=L10n.text("Actualización de WirePulse");alert.informativeText=status;alert.runModal()};installing=false;busy=false;installTask=nil}}
